------------ RefreshScrollView ------------

---刷新滑动列表
function CumulativeRechargeDialog:RefreshScrollView(result)
    local dataList = result or self.listRechargeZone
    if self.ListView.IsListViewInit then
        GameUtils.ReloadData(self.ListView, #self.listRechargeZone)
    else
        self.ListView:InitGridView(#self.listRechargeZone, Bind(self, self.OnGetItemByIndex))
    end
    local index = 0
    for i, v in ipairs(self.listRechargeZone) do
        if not CumulativeRechargeMgr:GetRewardAcquiredState(v.id) then
            index = i - 1
            break
        end
    end
    --self.ListView:MovePanelToItemByIndex(index)
    self:RefreshListViewPos()
end

---将目标cell居中
function CumulativeRechargeDialog:RefreshListViewPos()
    local index = #self.listRechargeZone
    for i, v in ipairs(self.listRechargeZone) do
        if not CumulativeRechargeMgr:GetRewardAcquiredState(v.id) then
            index = i
            break
        end
    end
    local contentW = self.ListViewContent.rect.width
    local paddingL = self.ListView.Padding.left
    local ItemSizeX = self.ListView.ItemSize.x
    local ItemPaddingX = self.ListView.ItemPadding.x
    local listW = self.controller.transform.rect.width
    local offsetX =  -paddingL - (index - 0.5) * ItemSizeX - (index - 1) * ItemPaddingX + listW / 2
    offsetX = math.min(0, offsetX)
    offsetX = math.max(-contentW + listW, offsetX)
    self.ListViewContent.anchoredPosition = Vector2.New(offsetX, 0)
end

---OnGetItemByIndex
---更新展示的列表元素
function CumulativeRechargeDialog:OnGetItemByIndex(gridView, index)
    if index < 0 then return end
    local cell = gridView:NewListViewItem(PATH_PREFAB)
    if not IsNull(cell) then
        local cellLB = GetLuaBehaviour(cell.gameObject, LUA_PATH_ITEM_CELL)
        if not IsNull(cellLB) then
            if isNull(cellLB.Env) then cellLB:Init() end
            local ltCell = cellLB.Env
            local rechargeLevel =  self.listRechargeZone[index + 1].id
            ltCell:SetCellInfo(rechargeLevel)
        end
    end
    return cell
end

