---刷新充值数量
function CumulativeRechargeDialog:RefreshNum()
    local num = CumulativeRechargeMgr:GetCurRechargeValue()
    CfUtils.FillText(self.TextNumber, num)
end

---刷新一键领取按钮
function CumulativeRechargeDialog:RefreshBtn()
    local listData = CumulativeRechargeMgr.listRechargeValue
    local curAmount = CumulativeRechargeMgr:GetCurRechargeValue()
    local redPointState = -1
    for i, v in ipairs(checkTable(listData)) do
        local acquired = CumulativeRechargeMgr:GetRewardAcquiredState(v.id)
        if not acquired and v.amount <= curAmount then
            redPointState = 0
            break
        end
    end
    CfUtils.SetActive(self.ImgBlack, redPointState == -1)
    self:RefreshRedPoint(redPointState)
end

---刷新红点
function CumulativeRechargeDialog:RefreshRedPoint(redPointState)
    GameUtils.UpdateServerRedPointData({unMallAccmulativePay = redPointState})
    Events.Broadcast(Constants.EventNames.StoreAccumulativePayRefresh)
end

---一键领取按钮点击事件处理
function CumulativeRechargeDialog:ButtonOnClickHandler()
    local listData = CumulativeRechargeMgr.listRechargeValue
    local curAmount = CumulativeRechargeMgr:GetCurRechargeValue()
    local hasRewards = false
    for i, v in ipairs(checkTable(listData)) do
        local acquired = CumulativeRechargeMgr:GetRewardAcquiredState(v.id)
        if not acquired and v.amount <= curAmount then
            hasRewards = true
            break
        end
    end
    if hasRewards then
        CumulativeRechargeMgr:DrawReward()
    else
        GameUtils.Toast(localize("当前没有可领取的奖励"))
    end
end
return CumulativeRechargeDialog